// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"bitcoin":{"slug":"bitcoin","cat":"basics","en":"Bitcoin (BTC)","contentLocale":"en","term":"Bitcoin (BTC)","aka":["BTC","XBT"],"short":"Bitcoin (BTC) is the first cryptocurrency, a decentralized digital money with a hard cap of 21 million coins that runs on its own proof-of-work blockchain.","body":[["Bitcoin was launched in 2009 by the pseudonymous ",["Satoshi","satoshi"]," Nakamoto. Miners around the world bundle transactions into a new block about every 10 minutes and receive newly created BTC plus fees as a reward. Every four years or so the block reward is cut in half in an event called the halving; the April 2024 halving reduced it to 3.125 BTC per block."],"The supply limit of 21 million BTC is written into the protocol, which is why many people see Bitcoin as digital scarcity rather than a payment app. Each bitcoin divides into 100,000,000 units called satoshis, so you can own a tiny fraction.",["You can buy BTC on centralized exchanges, hold it in a ",["self-custody wallet","non-custodial-wallet"],", or gain price exposure through products such as the US spot bitcoin ETFs that began trading in January 2024. On exchanges, BTC is the most liquid ",["crypto asset","cryptocurrency"],", with BTC/",["USDT","usdt"]," usually the deepest spot pair and the biggest ",["perpetual futures","perpetual-futures"]," market."]],"example":["Suppose BTC trades at 80,000 USDT and you want to invest 200 USDT. You would receive 0.0025 BTC, which equals 250,000 satoshis. If the price rises 5 percent to 84,000 USDT, your holding is worth 210 USDT. If you instead bought it with 3x ",["leverage","leverage"]," on futures, the same 5 percent move would change your margin by about 15 percent, in either direction."],"mistakes":["Waiting to afford a whole bitcoin, when you can buy any small fraction.","Sending BTC to an address on another network, such as a BEP20 or ERC20 address, without checking the exchange's supported withdrawal network.","Confusing Bitcoin with forks or similarly named tokens such as Bitcoin Cash or wrapped BTC."],"faq":[{"q":"How many bitcoins are there?","a":"The protocol caps supply at 21 million BTC. More than 19 million have already been mined, and the remaining coins are released more slowly after each halving."},{"q":"Who controls Bitcoin?","a":"No company or government controls the network. Changes require broad agreement among developers, miners, node operators and users."},{"q":"What is the difference between BTC and XBT?","a":"They are the same asset. XBT is an alternative ticker used by some exchanges and data providers to follow currency code conventions."}],"title":"What is Bitcoin (BTC)? Meaning, supply and how it works","description":"Learn what Bitcoin is, why its supply is capped at 21 million, how halvings work and how to buy a fraction of a BTC.","related":[["satoshi","Satoshi (sats)","A satoshi (sat) is the smallest unit of Bitcoin, equal to 0.00000001 BTC, so one bitcoin contains 100,000,000 satoshis."],["bitcoin-halving","Bitcoin halving","A Bitcoin halving is a pre-programmed event, roughly every four years, that cuts the number of new bitcoins paid to miners for each block by 50 percent."],["proof-of-work","Proof of work (PoW)","Proof of work (PoW) is a consensus mechanism in which miners use computing power to solve a puzzle, and the first to find a valid answer earns the right to add the next block and collect the reward."],["mining","Crypto mining","Crypto mining is the process of using specialised computers to secure a proof-of-work blockchain by adding new blocks, in exchange for newly issued coins and transaction fees."],["spot-bitcoin-etf","Spot bitcoin ETF","A spot bitcoin ETF is an exchange-traded fund that holds actual bitcoin and lets investors gain exposure to its price through a regular brokerage account."]],"lesson":{"id":"E01","slug":"can-i-buy-part-of-a-bitcoin","ep":1,"title":"One bitcoin costs that much. Can I still buy some?"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":true},"proof-of-work":{"slug":"proof-of-work","cat":"basics","en":"Proof of work (PoW)","contentLocale":"en","term":"Proof of work (PoW)","aka":["PoW"],"short":"Proof of work (PoW) is a consensus mechanism in which miners use computing power to solve a puzzle, and the first to find a valid answer earns the right to add the next block and collect the reward.","body":["Miners repeatedly hash a candidate block with a changing number until the result falls below a target set by the network. There is no shortcut; the only way is to try trillions of guesses. Finding a valid hash is hard, but anyone can check it instantly, which is what makes the system work.",["Because adding blocks costs real electricity and hardware, attacking a PoW chain is expensive. To rewrite history, an attacker would need more than half of the network's ",["hash rate","hash-rate"]," and would have to keep spending energy to stay ahead. ",["Bitcoin","bitcoin"]," is the best-known PoW network; Litecoin, Dogecoin and Bitcoin Cash also use it."],["The network adjusts difficulty automatically. On Bitcoin, difficulty changes every 2,016 blocks so blocks keep coming about every 10 minutes no matter how many miners join. Critics point to PoW's energy use, while supporters argue that the cost is exactly what secures the ledger. ",["Ethereum","ethereum"]," used PoW until it switched to ",["proof of stake","proof-of-stake"]," in September 2022."]],"example":"Suppose the Bitcoin network runs at 600 exahashes per second and a small mining farm contributes 6 exahashes per second, or 1 percent. With about 144 blocks per day, the farm can expect to win around 1.44 blocks daily on average. At 3.125 BTC per block, that is roughly 4.5 BTC per day before fees and electricity costs, though actual daily results vary with luck.","mistakes":["Thinking miners solve useful math problems; the puzzle is pure guessing designed to cost energy.","Assuming more miners means faster blocks, when difficulty adjusts to keep timing steady.","Believing a home computer can still mine Bitcoin profitably; specialised ASIC machines dominate."],"faq":[{"q":"What is the difference between proof of work and proof of stake?","a":"Proof of work secures the chain with computing power and electricity. Proof of stake secures it with coins locked up as collateral by validators."},{"q":"Why does Bitcoin use proof of work?","a":"It makes attacks costly in real-world resources and lets anyone verify which chain has the most work behind it, without trusting a central party."},{"q":"Is Ethereum still proof of work?","a":"No. Ethereum switched to proof of stake in September 2022 with the Merge."}],"title":"What is proof of work (PoW)? Meaning in crypto","description":"Learn how proof of work secures Bitcoin, why mining uses energy and how it differs from proof of stake.","related":[["mining","Crypto mining","Crypto mining is the process of using specialised computers to secure a proof-of-work blockchain by adding new blocks, in exchange for newly issued coins and transaction fees."],["hash-rate","Hash rate","Hash rate is the total computing power that miners use to secure a proof-of-work blockchain, measured in hashes per second."],["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) is a consensus mechanism in which validators lock up the network's coins as collateral to propose and confirm blocks, earning rewards for honest work and losing part of their stake for breaking the rules."],["blockchain","Blockchain","A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact."],["bitcoin-halving","Bitcoin halving","A Bitcoin halving is a pre-programmed event, roughly every four years, that cuts the number of new bitcoins paid to miners for each block by 50 percent."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"token-unlock":{"slug":"token-unlock","cat":"basics","en":"Token unlock","contentLocale":"en","term":"Token unlock","aka":["unlock","vesting unlock","token release"],"short":"A token unlock is a scheduled event when previously locked tokens, usually held by the team, investors or a treasury, become free to transfer and sell, increasing circulating supply.","body":["Most new projects do not release all tokens at launch. Insiders' tokens follow a vesting schedule, often with a cliff, a waiting period, followed by monthly or daily releases. Some unlocks are linear and small; others are one large cliff unlock that releases a big share at once.",["Unlocks matter because they add supply. If the people receiving tokens bought them at much lower prices, some may sell. Traders often watch large unlocks, especially those over a few percent of ",["circulating supply","circulating-supply"],", because they can weigh on the price. The market sometimes prices this in before the date."],["An unlock does not mean recipients will sell. Some stake or hold, and some unlocks go to ecosystem funds that release tokens slowly. Check who receives the tokens, how large the unlock is relative to daily ",["trading volume","trading-volume"],", and whether similar past unlocks led to selling."]],"example":["Suppose a token has 400 million in circulation at 0.80 ",["USDT","usdt"],", a ",["market cap","market-capitalization"]," of 320 million USDT, and averages 25 million USDT of daily trading volume. Next Tuesday, 60 million tokens unlock for early investors who paid 0.10 USDT. That unlock is 15 percent of circulating supply and worth about 48 million USDT at today's price, almost two days of normal trading volume."],"mistakes":["Ignoring the unlock calendar before buying a recently launched token.","Assuming every unlock causes a price drop; size, recipients and timing all matter.","Comparing an unlock to total supply instead of to circulating supply and daily volume."],"faq":[{"q":"Do token unlocks make the price go down?","a":"Not always. Large unlocks to insiders with low cost bases can add selling pressure, but the effect depends on demand, how much was already priced in and whether recipients sell."},{"q":"Where can I see token unlock schedules?","a":"Project documentation usually lists vesting terms, and token unlock tracking sites show upcoming events in a calendar."},{"q":"What is linear vesting?","a":"Linear vesting releases tokens in small equal amounts over time, such as every day or month, rather than in one lump sum."}],"title":"What is a token unlock? Meaning and why it matters","description":"Learn what a token unlock is, how vesting schedules work and how to judge whether an unlock is large.","related":[["tokenomics","Tokenomics","Tokenomics is the economic design of a cryptocurrency, covering how many tokens exist, who received them, how new tokens are released and what the token is actually used for."],["circulating-supply","Circulating supply","Circulating supply is the number of coins or tokens that are publicly available and moving in the market right now, excluding locked, reserved or burned tokens."],["fully-diluted-valuation","Fully diluted valuation (FDV)","Fully diluted valuation (FDV) is a project's value if all of its tokens that will ever exist were already in circulation, calculated as the current price multiplied by the maximum or total supply."],["airdrop","Airdrop","An airdrop is a distribution of free tokens to wallet addresses or exchange users, usually to reward early users, decentralize ownership or promote a new project."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"limit-order":{"slug":"limit-order","cat":"trading","en":"Limit order","contentLocale":"en","term":"Limit order","aka":["limit buy","limit sell"],"short":"A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher.","body":[["If ",["BTC","bitcoin"]," trades at 62,000 ",["USDT","usdt"]," and you place a buy limit at 61,000, your order rests in the ",["order book","order-book"]," until a seller is willing to trade at 61,000 or lower. If the price never drops there, your order never fills. You control the price, but you give up certainty of execution."],["A limit order placed away from the current price adds ",["liquidity","liquidity"]," to the book, so it is usually charged the lower ",["maker fee","maker-taker-fees"],". If you set a buy limit above the current ask, it fills immediately like a ",["market order","market-order"]," and pays the taker fee, unless you choose a post-only option."],"Limit orders can be partially filled. If you want 1 BTC at 61,000 and only 0.3 BTC is offered there, you get 0.3 and the rest waits. You can choose how long the order stays active with time-in-force settings such as GTC, IOC or FOK."],"example":"Suppose ETH trades at 2,600 USDT and you place a buy limit for 2 ETH at 2,500. Two days later the price dips to 2,480 and your order fills at 2,500, costing 5,000 USDT. With a maker fee of 0.08 percent you pay 4 USDT in fees. If you had used a market order at 2,600, you would have paid 5,200 USDT plus a 0.1 percent taker fee of 5.20 USDT. But if ETH had bounced at 2,520, your limit order would never have filled.","mistakes":["Setting a buy limit above the market price and paying taker fees by accident.","Forgetting about open limit orders that fill days later when market conditions have changed.","Assuming a limit order guarantees a fill when the price touches your level; there may be orders ahead of you in the queue."],"faq":[{"q":"What happens if my limit order does not fill?","a":"It stays open until it fills, you cancel it, or it expires according to its time-in-force setting. No funds are spent until it executes."},{"q":"Why did the price touch my limit but my order did not fill?","a":"Other orders at the same price were placed earlier and were filled first, and the price moved away before reaching yours."},{"q":"Are limit orders cheaper?","a":"Often yes. Limit orders that rest on the book are usually charged maker fees, which are lower than taker fees on most exchanges."}],"title":"What is a limit order in crypto? Meaning and example","description":"Learn how a limit order works, why it usually pays maker fees and why it may not fill even when price comes close.","related":[["market-order","Market order","A market order is an instruction to buy or sell immediately at the best price currently available in the order book, prioritising speed of execution over a specific price."],["post-only-order","Post-only order","A post-only order is a limit order that is only allowed to add liquidity to the order book; if it would fill immediately against an existing order, the exchange cancels or adjusts it instead."],["time-in-force","Time in force (GTC, IOC, FOK)","Time in force is an order setting that controls how long an order stays active and how it handles partial fills, with common options GTC (good till cancelled), IOC (immediate or cancel) and FOK (fill or kill)."],["order-book","Order book","An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level."],["maker-taker-fees","Maker and taker fees","Maker and taker fees are the two trading fee rates an exchange charges: a maker fee when your order adds liquidity to the order book, and a usually higher taker fee when your order removes it."]],"lesson":{"id":"E14","slug":"market-limit-cancel","ep":14,"title":"Market, limit, cancel: what does each one solve?"},"coin":null,"tool":null,"cta":true},"insurance-fund":{"slug":"insurance-fund","cat":"derivatives","en":"Insurance fund","contentLocale":"en","term":"Insurance fund","aka":["liquidation insurance fund","risk fund"],"short":"An insurance fund is a reserve an exchange keeps to cover losses when liquidated positions cannot be closed at a price good enough to repay what they owe.","body":["When a position is liquidated, the exchange tries to close it before the trader's margin runs out completely. If it closes at a better price than the bankruptcy price, the leftover margin usually goes into the insurance fund. If the market gaps and the fill is worse than the bankruptcy price, the fund pays the shortfall.",["Without this buffer, profitable traders on the other side might not receive their full gains. The insurance fund is the first line of defence; ",["auto-deleveraging (ADL)","auto-deleveraging"]," only comes in when the fund is not enough. Some exchanges keep separate funds per ",["contract","smart-contract"],", others pool them."],["Large exchanges publish their insurance fund balances, which helps you judge how well a market can handle extreme moves. A small or shrinking fund on an illiquid contract means a higher chance of ADL. On-chain perp exchanges use similar mechanisms, sometimes with a vault funded by ",["liquidity","liquidity"]," providers instead."]],"example":["Suppose a trader's long has a bankruptcy price of 28,000 ",["USDT","usdt"],". In a fast drop, the ",["liquidation","liquidation"]," engine fills the position at 27,800, a 200 USDT gap per ",["BTC","bitcoin"]," on a 5 BTC position. The shortfall of 5 × 200 = 1,000 USDT comes from the insurance fund. Earlier that day another liquidation closed at 300 USDT per BTC better than its bankruptcy price on 2 BTC, adding 600 USDT to the fund."],"mistakes":["Thinking the insurance fund protects your own margin from liquidation.","Assuming the fund size is the same for every contract on an exchange.","Ignoring a small insurance fund when trading high leverage on illiquid contracts."],"faq":[{"q":"Does the insurance fund pay me if I get liquidated?","a":"No. It covers losses beyond the liquidated trader's margin so the exchange and counterparties are paid. Your liquidated margin is not refunded."},{"q":"Where does the insurance fund money come from?","a":"Mainly from leftover margin when liquidations close at better than the bankruptcy price, and sometimes from exchange contributions."}],"title":"What is an insurance fund in crypto futures?","description":"Learn how a crypto exchange insurance fund works, where its money comes from and how it links to liquidation and ADL.","related":[["auto-deleveraging","Auto-deleveraging (ADL)","Auto-deleveraging (ADL) is a last-resort mechanism where an exchange automatically reduces profitable opposing positions to cover a liquidation that the market and insurance fund cannot absorb."],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."],["proof-of-reserves","Proof of reserves","Proof of reserves is a report in which a crypto exchange shows that the assets it holds in wallets it controls are at least equal to the balances it owes its customers."],["mark-price","Mark price","The mark price is a fair-value price an exchange uses to calculate unrealized profit and loss and to trigger liquidations, instead of the last traded price."]],"lesson":{"id":"E23","slug":"liquidation-mark-price","ep":23,"title":"Liquidation: who pressed the forced-close button?"},"coin":null,"tool":"/liquidations","cta":false},"block-confirmations":{"slug":"block-confirmations","cat":"wallets-security","en":"Block confirmations","contentLocale":"en","term":"Block confirmations","aka":["confirmations","network confirmations"],"short":"Block confirmations are the number of blocks added to a blockchain since the block that includes your transaction, and exchanges wait for a set number before crediting a deposit.","body":["When your transaction is included in a block, it has 1 confirmation. Each new block on top adds another. The deeper a transaction sits, the harder it is for the chain to reorganise and drop it, so more confirmations mean more certainty.",["Exchanges set their own confirmation requirements for each network, which you can usually see on the deposit page. Requirements also differ by chain: ",["Bitcoin","bitcoin"]," blocks arrive roughly every 10 minutes, while chains like Tron or Solana produce blocks in seconds. Some exchanges credit a deposit for trading after fewer confirmations but unlock withdrawal only after more."],"If your deposit shows on an explorer but not on the exchange yet, compare the current confirmation count with the exchange's requirement before contacting support."],"example":"Imagine you deposit 0.1 BTC and the exchange requires 2 confirmations to credit and 3 to unlock withdrawal (illustrative numbers). Your transaction enters a block at 14:00. Blocks follow at about 14:09 and 14:21. At 14:09 you have 2 confirmations and the 0.1 BTC appears in your balance. At 14:21 you reach 3 and can withdraw it. Since Bitcoin block times vary, the same deposit could take longer.","mistakes":["Contacting support before the deposit has reached the required number of confirmations.","Expecting every network to confirm as fast as the one you used last time.","Treating a transaction with 0 confirmations as final."],"faq":[{"q":"How many confirmations does Bitcoin need?","a":"There is no single rule. Each exchange sets its own number, and many merchants and individuals treat a few confirmations as sufficient for typical amounts."},{"q":"Why is my transaction stuck at 0 confirmations?","a":"It is still waiting in the mempool, often because the fee was low compared with other pending transactions."}],"title":"What are block confirmations? Why deposits wait","description":"What block confirmations are, why exchanges wait for them, and how to check if your deposit is still confirming.","related":[["transaction-hash","Transaction hash (TxID)","A transaction hash, or TxID, is the unique identifier of a blockchain transaction, which you can paste into a block explorer to see its status, amount, addresses and confirmations."],["block-explorer","Block explorer","A block explorer is a website or app that lets you search a blockchain's public records, including transactions, addresses, blocks and token transfers."],["mempool","Mempool","The mempool is the waiting area where valid but unconfirmed transactions sit on network nodes until a miner or validator includes them in a block."],["blockchain","Blockchain","A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact."]],"lesson":{"id":"E10","slug":"transfer-not-arrived","ep":10,"title":"It says sent, but it never arrived. Where do you look?"},"coin":null,"tool":null,"cta":false},"impermanent-loss":{"slug":"impermanent-loss","cat":"defi","en":"Impermanent loss","contentLocale":"en","term":"Impermanent loss","aka":["IL","divergence loss"],"short":"Impermanent loss is the shortfall a liquidity provider has compared with simply holding the same tokens, caused by the prices of the pooled tokens moving apart after the deposit.","body":[["In an ",["AMM","amm"]," pool, ",["arbitrage","arbitrage"]," traders rebalance the pool as prices move. If one token rises, the pool sells some of it for the other. When you withdraw, you hold less of the token that went up and more of the one that went down than if you had just held them."],"It is called impermanent because the gap shrinks if prices return to where they were when you deposited. If you withdraw while prices have moved, the loss becomes real. Trading fees and rewards can offset it, but not always.",["The bigger the price divergence, the bigger the loss. In a standard 50/50 pool, a 2x price change in one token relative to the other costs about 5.7 percent versus holding. ",["Stablecoin","stablecoin"]," pairs and correlated assets usually have far less impermanent loss, while concentrated ",["liquidity","liquidity"]," positions can suffer more."]],"example":["Suppose you deposit 1 ",["ETH","ethereum"]," and 2,000 ",["USDC","usdc"]," into a 50/50 pool when ETH is 2,000 USDC, for a total value of 4,000 USDC. ETH doubles to 4,000 USDC. Rebalancing leaves you with about 0.707 ETH and 2,828 USDC, worth about 5,657 USDC. Had you just held, you would have 1 ETH plus 2,000 USDC, worth 6,000 USDC. The difference of about 343 USDC, 5.7 percent, is impermanent loss before fees."],"mistakes":["Assuming impermanent loss only happens when prices fall.","Comparing pool returns with zero instead of with simply holding the two tokens.","Ignoring that concentrated liquidity ranges can magnify the loss."],"faq":[{"q":"Can trading fees cover impermanent loss?","a":"Sometimes. If the pool earns enough fees during your deposit period, they can outweigh the loss, but in volatile markets they often do not."},{"q":"Does impermanent loss happen in stablecoin pools?","a":"Very little while both stablecoins stay at their peg. A depeg of one coin can cause real losses."}],"title":"What is impermanent loss? Example and formula","description":"Learn what impermanent loss is, why it happens in AMM pools, and how to calculate it with a worked example.","related":[["liquidity-pool","Liquidity pool","A liquidity pool is a smart contract holding two or more tokens that traders swap against on a DEX, funded by liquidity providers who earn a share of the trading fees."],["amm","Automated market maker (AMM)","An automated market maker (AMM) is a type of DEX that prices trades with a mathematical formula based on the tokens held in a liquidity pool, instead of matching buyers and sellers in an order book."],["yield-farming","Yield farming","Yield farming is the practice of moving crypto into DeFi protocols, such as liquidity pools or lending markets, to earn trading fees, interest and extra token rewards."],["apr-vs-apy","APR vs APY","APR is the simple annual rate of return or interest without compounding, while APY includes the effect of reinvesting earnings, so APY is higher than APR whenever returns compound."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"liquid-staking":{"slug":"liquid-staking","cat":"defi","en":"Liquid staking","contentLocale":"en","term":"Liquid staking","aka":["LST","liquid staking token","liquid staking derivative"],"short":"Liquid staking is a way to stake coins through a protocol that issues a tradable token, such as stETH, representing your staked position, so you earn staking rewards and can still use or sell the token.","body":[["Normal ",["staking","staking"]," locks your coins. With liquid staking, you deposit ",["ETH","ethereum"]," or SOL into a protocol such as Lido, Rocket Pool or Jito. It stakes on your behalf and gives you a liquid staking token. Some tokens grow in number each day, others rise in value against the underlying coin."],["You can hold the token to earn rewards, trade it on a ",["DEX","dex"],", or use it as collateral in ",["DeFi","defi"],". That flexibility is why liquid staking became one of the largest DeFi categories."],["The risks: a ",["smart contract","smart-contract"]," bug in the protocol, slashing of its validators, and the token trading below the value of the coin it represents, a ",["depeg","depeg"],". A depeg matters mostly if you need to sell quickly or used the token as collateral for a loan."]],"example":"Say you deposit 5 ETH into a liquid staking protocol and receive 5 stETH. With an illustrative 3 percent yearly reward, your balance grows to about 5.15 stETH after a year. Halfway through, you need cash and see stETH trading at 0.99 ETH on a DEX. Selling 5.07 stETH at that rate returns about 5.02 ETH, slightly less than waiting for the protocol's withdrawal queue, which can take days.","mistakes":["Assuming a liquid staking token is always worth exactly one unit of the underlying coin.","Borrowing heavily against an LST, which can be liquidated if it trades below its peg.","Not knowing whether your token rebases or grows in value, then misreading your balance."],"faq":[{"q":"What is the difference between staking and liquid staking?","a":"Standard staking locks your coins. Liquid staking gives you a token that represents the staked coins and can be traded or used in DeFi."},{"q":"Is stETH the same as ETH?","a":"No. stETH is a token issued by Lido that represents staked ETH. It usually trades close to ETH but can trade at a discount."}],"title":"What is liquid staking? Meaning and risks","description":"How liquid staking works, what tokens like stETH represent, and the depeg and smart contract risks to understand.","related":[["staking","Staking","Staking is locking up coins of a proof-of-stake blockchain to help validate transactions and secure the network, in return for staking rewards paid in that coin."],["restaking","Restaking","Restaking is reusing already staked ETH, or a liquid staking token, to also secure additional services, earning extra rewards in exchange for extra slashing and smart contract risk."],["wrapped-token","Wrapped token","A wrapped token is a token on one blockchain that represents another asset one-to-one, such as WBTC representing bitcoin on Ethereum, backed by the original asset held by a custodian or smart contract."],["depeg","Depeg","A depeg is when a stablecoin or pegged token trades meaningfully away from the value it is designed to track, such as a dollar stablecoin falling below 1 USD."]],"lesson":null,"coin":{"slug":"lido-dao","name":"Lido DAO","symbol":"LDO"},"tool":null,"cta":false},"restaking":{"slug":"restaking","cat":"defi","en":"Restaking","contentLocale":"en","term":"Restaking","aka":["liquid restaking","LRT"],"short":"Restaking is reusing already staked ETH, or a liquid staking token, to also secure additional services, earning extra rewards in exchange for extra slashing and smart contract risk.","body":[["EigenLayer popularised restaking on ",["Ethereum","ethereum"],". Stakers opt in to let their staked ETH secure other systems, such as data availability layers, oracles or bridges, often called actively validated services. If the operator they delegate to breaks the rules of those services, part of the stake can be slashed."],["Liquid restaking protocols, such as those issuing tokens like ezETH, rsETH or weETH, wrap this process: you deposit ETH or an ",["LST","liquid-staking"]," and receive a liquid restaking token that you can trade or use in ",["DeFi","defi"],"."],["Each layer adds a risk. You carry Ethereum ",["staking","staking"]," risk, the restaking protocol's ",["contract","smart-contract"]," risk, the slashing rules of every service secured, and the risk that the liquid restaking token trades below its underlying value. Extra yield is payment for those risks."]],"example":"Imagine you hold 4 stETH earning an illustrative 3 percent staking reward. You restake them through a liquid restaking protocol and receive a token that adds an estimated 1.5 percent in extra rewards. On 4 ETH worth of stake, that is about 0.12 ETH a year from staking plus 0.06 ETH from restaking. If an operator is slashed 2 percent for misbehaviour, you could lose about 0.08 ETH, wiping out most of the extra rewards.","mistakes":["Treating restaking yield as risk-free because the underlying asset is ETH.","Ignoring that liquid restaking tokens can be harder to sell quickly than ETH or stETH.","Looping restaking tokens with borrowing without understanding liquidation thresholds."],"faq":[{"q":"What is the difference between staking and restaking?","a":"Staking secures the Ethereum network itself. Restaking extends the same stake to secure additional services, adding new rewards and new slashing risks."},{"q":"Is EigenLayer the only restaking protocol?","a":"No. EigenLayer is the best known on Ethereum, but other restaking protocols exist on Ethereum and other networks."}],"title":"What is restaking? EigenLayer and LRTs explained","description":"What restaking is, how liquid restaking tokens work, and the extra slashing and contract risks that come with extra yield.","related":[["liquid-staking","Liquid staking","Liquid staking is a way to stake coins through a protocol that issues a tradable token, such as stETH, representing your staked position, so you earn staking rewards and can still use or sell the token."],["staking","Staking","Staking is locking up coins of a proof-of-stake blockchain to help validate transactions and secure the network, in return for staking rewards paid in that coin."],["validator","Validator","A validator is a participant in a proof-of-stake blockchain that locks up coins as collateral and runs software to propose new blocks and vote on whether other blocks are valid."],["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"defi-lending":{"slug":"defi-lending","cat":"defi","en":"DeFi lending","contentLocale":"en","term":"DeFi lending","aka":["crypto lending protocol","money market","decentralized lending"],"short":"DeFi lending is borrowing and lending crypto through smart contracts, where lenders earn interest from a shared pool and borrowers must lock more collateral than they borrow.","body":[["On protocols such as Aave, Compound or Morpho, lenders deposit tokens into a pool and earn a variable interest rate that rises when more of the pool is borrowed. Borrowers deposit collateral, such as ",["ETH","ethereum"],", and can borrow other assets up to a loan-to-value limit set for that collateral."],["Loans are overcollateralized because there is no credit check. If the collateral value falls and your health factor drops below 1, part of your collateral can be sold to liquidators at a discount to repay the debt. Prices come from oracles, so a sharp price move is enough to trigger ",["liquidation","liquidation"],"."],["Risks for lenders include ",["smart contract","smart-contract"]," bugs, bad debt if liquidations fail during crashes, and periods when the pool is fully borrowed and withdrawals must wait."]],"example":["Suppose you deposit 2 ETH at 3,000 ",["USDC","usdc"]," each, worth 6,000 USDC, with a liquidation threshold of 80 percent, an illustrative setting. You borrow 3,000 USDC. Your health factor is 6,000 times 0.8 divided by 3,000, which is 1.6. If ETH falls to 1,875 USDC, your collateral is worth 3,750 USDC and the health factor drops to 1.0. Below that, liquidators can repay part of your loan and take ETH plus a bonus."],"mistakes":["Borrowing close to the maximum and leaving no buffer for price drops.","Not watching the health factor during volatile markets.","Assuming lending interest is fixed when most DeFi rates change every block."],"faq":[{"q":"Why do DeFi loans need more collateral than the loan?","a":"There is no identity or credit check, so the protocol protects lenders by requiring collateral worth more than the loan and liquidating it if its value falls too far."},{"q":"Where does DeFi lending interest come from?","a":"From borrowers who pay interest to use the pool's tokens, sometimes topped up by reward tokens."}],"title":"What is DeFi lending? How crypto loans work","description":"How DeFi lending protocols work, why loans are overcollateralized, and how the health factor triggers liquidation.","related":[["defi","DeFi (decentralized finance)","DeFi, short for decentralized finance, is a set of financial services such as trading, lending and earning yield that run on public blockchains through smart contracts instead of through banks or exchanges."],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement."],["oracle","Blockchain oracle","A blockchain oracle is a service that brings outside data, most often asset prices, onto a blockchain so smart contracts can use it for actions like liquidations, settlements and swaps."],["crypto-backed-stablecoin","Crypto-backed stablecoin","A crypto-backed stablecoin is a stablecoin issued against crypto collateral locked in smart contracts, usually worth more than the coins created, so the token can stay near 1 USD."],["flash-loan","Flash loan","A flash loan is an uncollateralized DeFi loan that must be borrowed and repaid, with a fee, within the same blockchain transaction, or the whole transaction is cancelled."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cbdc":{"slug":"cbdc","cat":"stablecoins","en":"CBDC (central bank digital currency)","contentLocale":"en","term":"CBDC (central bank digital currency)","aka":["CBDC","central bank digital currency","digital fiat"],"short":"A CBDC (central bank digital currency) is a digital form of a country's official money issued and backed directly by its central bank, not by a private company.","body":["Cash is a direct claim on the central bank, while the money in your bank account is a claim on a commercial bank. A CBDC would give people or institutions a digital claim directly on the central bank. China's e-CNY pilot and the Bahamas' Sand Dollar are well-known examples, and the European Central Bank has been preparing a digital euro.",["There are two main types. Retail CBDCs are meant for everyday payments by the public. Wholesale CBDCs are for settlement between banks and financial institutions. A CBDC may or may not run on a ",["blockchain","blockchain"],"; many designs use a centralized ledger controlled by the central bank."],["A CBDC is not a ",["cryptocurrency","cryptocurrency"]," like ",["bitcoin","bitcoin"],", and it is not a ",["stablecoin","stablecoin"],". Stablecoins such as ",["USDT","usdt"]," or ",["USDC","usdc"]," are issued by private companies and backed by their reserves. A CBDC is legal money issued by the state, which also raises debates about privacy, spending limits and the role of commercial banks. Designs and timelines differ widely by country."]],"example":"Imagine a country launches a retail CBDC with a holding limit of 3,000 units per person. You receive a salary of 4,000 units into your bank account and move 1,000 into your CBDC wallet to pay a shop. The shop receives the payment instantly in central bank money. If you tried to move another 2,500, only 2,000 would fit under the limit, and the rest would stay in your bank account.","mistakes":["Confusing a CBDC with a private stablecoin that only tracks the same currency.","Assuming every CBDC runs on a public blockchain that anyone can inspect.","Believing a CBDC can be traded on crypto exchanges like other tokens."],"faq":[{"q":"Is a CBDC a cryptocurrency?","a":"No. A CBDC is official government money in digital form. It is centrally issued and controlled, unlike decentralized cryptocurrencies such as bitcoin."},{"q":"What is the difference between a CBDC and a stablecoin?","a":"A CBDC is issued by a central bank and is a direct liability of that bank. A stablecoin is issued by a private company and is only as reliable as its reserves and redemption process."}],"title":"What is a CBDC? Central bank digital currency explained","description":"What a CBDC is, how retail and wholesale CBDCs work, and how a central bank digital currency differs from crypto and stablecoins.","related":[["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."],["fiat-on-ramp","Fiat on-ramp","A fiat on-ramp is any service that turns government money like dollars or euros into crypto, such as a bank transfer to an exchange, a card purchase or a P2P trade."],["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie."],["blockchain","Blockchain","A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"Is USDT a dollar? Why is it everywhere when you buy crypto?"},"coin":null,"tool":null,"cta":false},"node":{"slug":"node","cat":"onchain","en":"Node","contentLocale":"en","term":"Node","aka":["full node","blockchain node"],"short":"A node is a computer running a blockchain's software that stores, checks and relays transactions and blocks, helping keep the network decentralized and honest.","body":[["A ",["blockchain","blockchain"]," has no central server. Instead, thousands of nodes each keep a copy of the ledger and follow the same rules. When a new transaction or block arrives, every node independently checks that it is valid before passing it on. Invalid data is rejected, no matter who sent it."],["There are several types. A full node downloads and verifies the entire chain. An archive node also keeps every historical state, which apps and explorers need. A light node keeps only small parts and relies on full nodes for the rest. Mining nodes on proof-of-work chains and ",["validator","validator"]," nodes on proof-of-stake chains also propose or attest to new blocks."],["Running your own ",["Bitcoin","bitcoin"]," or ",["Ethereum","ethereum"]," node lets you verify your transactions without trusting a third party and adds to network resilience. It needs storage, bandwidth and some maintenance. Most wallets connect to public nodes run by providers, which is convenient but means you trust their data and they can see your queries."]],"example":"Suppose you run a Bitcoin full node at home. A block arrives claiming a miner reward of 6.25 BTC, but under current rules after the April 2024 halving the subsidy is 3.125 BTC plus fees. If fees in that block total 0.2 BTC, the maximum allowed reward is 3.325 BTC. Your node sees the 6.25 BTC claim exceeds that limit by 2.925 BTC, rejects the block and does not relay it, even if the miner is large.","mistakes":["Thinking a node and a validator are always the same; many nodes only verify and relay.","Assuming a wallet app runs its own node when it actually relies on a provider.","Expecting to earn rewards just by running a regular full node."],"faq":[{"q":"Do you get paid for running a Bitcoin node?","a":"No, a regular Bitcoin full node earns nothing directly. People run nodes to verify transactions themselves and support the network. Miners earn rewards, but that is a separate role."},{"q":"What is the difference between a node and a validator?","a":"A node stores and checks blockchain data. A validator is a node on a proof-of-stake chain that has staked coins and takes part in proposing and attesting blocks."}],"title":"What is a node in blockchain? Full nodes explained","description":"What a blockchain node is, how full, light and archive nodes differ, and why running your own node lets you verify transactions.","related":[["blockchain","Blockchain","A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact."],["validator","Validator","A validator is a participant in a proof-of-stake blockchain that locks up coins as collateral and runs software to propose new blocks and vote on whether other blocks are valid."],["mining","Crypto mining","Crypto mining is the process of using specialised computers to secure a proof-of-work blockchain by adding new blocks, in exchange for newly issued coins and transaction fees."],["mempool","Mempool","The mempool is the waiting area where valid but unconfirmed transactions sit on network nodes until a miner or validator includes them in a block."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"aml":{"slug":"aml","cat":"regulation","en":"AML (anti-money laundering)","contentLocale":"en","term":"AML (anti-money laundering)","aka":["AML","anti-money laundering","AML/CFT"],"short":"AML (anti-money laundering) is the set of laws and internal controls that financial firms, including crypto exchanges, use to detect and prevent illegal funds from entering the system.","body":[["AML covers more than identity checks. It includes customer due diligence, ongoing transaction monitoring, sanctions screening, record keeping and reporting suspicious activity to authorities. ",["KYC","kyc"]," is the first step; AML is the whole programme around it. It often appears together with CFT, countering the financing of terrorism."],["In crypto, exchanges use ",["blockchain","blockchain"]," analytics to score incoming deposits. Funds linked to hacks, sanctioned addresses, darknet markets or certain mixers may be flagged. A flagged deposit can lead to questions about the source of funds, a temporary hold, or in serious cases a frozen account while the exchange investigates."],["For ordinary users, AML mostly shows up as checks you can prepare for: being asked where your money came from, why you are sending large amounts, or who you are trading with on ",["P2P","p2p-trading"],". The international standards come from the FATF, and each country turns them into its own rules, so procedures vary by exchange and region."]],"example":["Suppose you receive 8,000 ",["USDT","usdt"]," from a P2P buyer and deposit it to a ",["centralized exchange","centralized-exchange"],". The exchange's analytics tool shows that 2,000 USDT of it passed recently through an address linked to a reported scam. That is 25% of the deposit. The exchange places a hold on the 8,000 USDT and asks for your P2P order history and chat records. Providing clear records helps the review, but the outcome depends on the exchange's policy."],"mistakes":["Accepting P2P payments from third parties whose names do not match the buyer's account.","Ignoring a source-of-funds request, which often leads to longer holds.","Routing funds through mixers or unknown wallets to look private, which can trigger AML flags."],"faq":[{"q":"What is the difference between KYC and AML?","a":"KYC is verifying who a customer is. AML is the broader programme that includes KYC plus monitoring transactions, screening sanctions and reporting suspicious activity."},{"q":"Why was my crypto deposit frozen for AML review?","a":"The exchange's monitoring likely linked the funds or the transaction pattern to a risk. Respond through official support with documents showing where the funds came from."}],"title":"What is AML in crypto? Anti-money laundering explained","description":"What AML means for crypto exchanges, how transaction monitoring and source-of-funds checks work, and why deposits get frozen.","related":[["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie."],["travel-rule","Travel rule","The travel rule is an anti-money laundering requirement that makes crypto service providers share sender and recipient information when they transfer crypto for customers."],["vasp","VASP (virtual asset service provider)","A VASP (virtual asset service provider) is a business that exchanges, transfers, holds or manages crypto for customers and must follow anti-money laundering rules where it operates."],["p2p-trading","P2P (C2C) trading","P2P (C2C) trading is buying or selling crypto directly with another user, paying in local money through bank transfer or payment apps while the platform holds the crypto in escrow."]],"lesson":{"id":"E05","slug":"kyc-who-gets-your-id","ep":5,"title":"How does KYC work, and who should get your ID?"},"coin":null,"tool":null,"cta":false},"tokenized-gold":{"slug":"tokenized-gold","cat":"tokenized-assets","en":"Tokenized gold","contentLocale":"en","term":"Tokenized gold","aka":["gold token","gold-backed token","PAXG","XAUT"],"short":"Tokenized gold is a blockchain token backed by physical gold held in a vault, where each token represents a set amount of gold, often one fine troy ounce.","body":["The issuer buys gold bars, stores them with a vault provider and issues tokens against them. Pax Gold (PAXG), issued by Paxos, and Tether Gold (XAUT) are the best-known examples, with each token representing one fine troy ounce of gold. Holders can trade the token on exchanges, move it on-chain or, under certain conditions, redeem it.",["The advantage is that you can hold gold exposure in a ",["crypto wallet","crypto-wallet"],", trade in small fractions and move value at any time of day. The token price follows the gold spot price closely, though small premiums or discounts can appear when crypto markets are trading and traditional gold markets are closed."],"Your safety depends on the issuer's honesty, regular audits or attestations of the gold reserves, and the legal right to redeem. Physical redemption often has minimum amounts and fees, and some products allow redemption only for verified customers. Check these details for any gold token you hold."],"example":"Suppose gold trades at 2,400 USD per ounce and one token represents one ounce. You buy 0.25 tokens for about 600 USD. If gold rises 5% to 2,520 USD, your 0.25 tokens are worth about 630 USD. If you instead wanted to redeem for a physical bar, a minimum of, say, 400 ounces could apply, which would be about 960,000 USD at 2,400 USD per ounce.","mistakes":["Assuming every gold token is equally audited and redeemable.","Expecting to redeem a small balance for physical gold when minimums apply.","Confusing a gold-backed token with a token that only tracks gold price through derivatives."],"faq":[{"q":"Is PAXG backed by real gold?","a":"Paxos states that each PAXG is backed by one fine troy ounce of gold held in professional vaults, with regular reserve attestations."},{"q":"Can I redeem tokenized gold for physical gold?","a":"Some issuers allow it for verified customers, usually with minimum amounts and fees. Smaller holders typically sell the token for cash or stablecoins instead."}],"title":"What is tokenized gold? Gold-backed tokens explained","description":"How tokenized gold like PAXG and XAUT works, what backs each token, how redemption works and the issuer risks to check.","related":[["real-world-assets","Real-world assets (RWA)","Real-world assets (RWA) are traditional assets such as bonds, gold, real estate, private credit or stocks represented as tokens on a blockchain."],["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms."],["custodial-wallet","Custodial wallet","A custodial wallet is a crypto wallet where a third party, usually an exchange or app, holds the private keys and controls the funds on your behalf."],["tokenized-stocks","Tokenized stocks","Tokenized stocks are blockchain tokens designed to track the price of a company's shares, usually backed one to one by real shares held by a custodian."]],"lesson":null,"coin":{"slug":"pax-gold","name":"PAX Gold","symbol":"PAXG"},"tool":"/topics/tokenized-assets","cta":false}});
